<?php
/** LLM APIs: messages and roles, tokens and costs, streaming, tool use, keys and errors, structured output, prompt caching and batches, images and documents. Examples with the Anthropic Python SDK. */

if (!function_exists('fig_llmapi_history')) {
    function fig_llmapi_history(string $call, string $tok, string $note): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 300" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><text x="20" y="30" font-weight="700">{$call} 1</text><rect x="20" y="44" width="190" height="30" rx="7" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="32" y="64" font-size="13">system</text><rect x="20" y="80" width="190" height="30" rx="7" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="3"/><text x="32" y="100" font-size="13">user ★</text><text x="20" y="132" font-size="13" fill="#5E5B85">≈ 300 {$tok}</text><text x="225" y="30" font-weight="700">{$call} 2</text><rect x="225" y="44" width="190" height="30" rx="7" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="237" y="64" font-size="13">system</text><rect x="225" y="80" width="190" height="30" rx="7" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="237" y="100" font-size="13">user</text><rect x="225" y="116" width="190" height="30" rx="7" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="237" y="136" font-size="13">assistant</text><rect x="225" y="152" width="190" height="30" rx="7" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="3"/><text x="237" y="172" font-size="13">user ★</text><text x="225" y="204" font-size="13" fill="#5E5B85">≈ 900 {$tok}</text><text x="430" y="30" font-weight="700">{$call} 3</text><rect x="430" y="44" width="190" height="30" rx="7" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="442" y="64" font-size="13">system</text><rect x="430" y="80" width="190" height="30" rx="7" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="442" y="100" font-size="13">user</text><rect x="430" y="116" width="190" height="30" rx="7" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="442" y="136" font-size="13">assistant</text><rect x="430" y="152" width="190" height="30" rx="7" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="442" y="172" font-size="13">user</text><rect x="430" y="188" width="190" height="30" rx="7" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="442" y="208" font-size="13">assistant</text><rect x="430" y="224" width="190" height="30" rx="7" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="3"/><text x="442" y="244" font-size="13">user ★</text><text x="430" y="276" font-size="13" fill="#5E5B85">≈ 1700 {$tok}</text><text x="20" y="290" font-size="13" fill="#5E5B85">{$note}</text></svg>
SVG;
    }
}

if (!function_exists('fig_llmapi_stream')) {
    function fig_llmapi_stream(string $without, string $with, string $wait, string $all, string $w0, string $w1, string $w2, string $w3, string $w4, string $w5, string $first): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 260" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><style>.sw0{animation:sw0 9s linear infinite}@keyframes sw0{0%,8%{opacity:1}9%,14%{opacity:0}15%,100%{opacity:1}}.sw1{animation:sw1 9s linear infinite}@keyframes sw1{0%,8%{opacity:1}9%,22%{opacity:0}23%,100%{opacity:1}}.sw2{animation:sw2 9s linear infinite}@keyframes sw2{0%,8%{opacity:1}9%,30%{opacity:0}31%,100%{opacity:1}}.sw3{animation:sw3 9s linear infinite}@keyframes sw3{0%,8%{opacity:1}9%,38%{opacity:0}39%,100%{opacity:1}}.sw4{animation:sw4 9s linear infinite}@keyframes sw4{0%,8%{opacity:1}9%,46%{opacity:0}47%,100%{opacity:1}}.sw5{animation:sw5 9s linear infinite}@keyframes sw5{0%,8%{opacity:1}9%,54%{opacity:0}55%,100%{opacity:1}}.sb{animation:sbin 9s linear infinite}@keyframes sbin{0%,8%{opacity:1}9%,62%{opacity:0}63%,100%{opacity:1}}@media (prefers-reduced-motion:reduce){.sw0,.sw1,.sw2,.sw3,.sw4,.sw5,.sb{animation:none}}</style><line x1="150" y1="214" x2="620" y2="214" stroke="#8A87B0" stroke-width="2"/><text x="150" y="234" text-anchor="middle" font-size="13" fill="#5E5B85">0 s</text><text x="266" y="234" text-anchor="middle" font-size="13" fill="#5E5B85">2 s</text><text x="382" y="234" text-anchor="middle" font-size="13" fill="#5E5B85">4 s</text><text x="498" y="234" text-anchor="middle" font-size="13" fill="#5E5B85">6 s</text><text x="614" y="234" text-anchor="middle" font-size="13" fill="#5E5B85">8 s</text><text x="20" y="72" font-weight="700">{$without}</text><text x="20" y="152" font-weight="700">{$with}</text><rect x="150" y="50" width="290" height="34" rx="8" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2" stroke-dasharray="5 4"/><text x="295.0" y="72" text-anchor="middle" font-size="13" fill="#5E5B85">{$wait}</text><rect class="sb" x="444" y="50" width="174" height="34" rx="8" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text class="sb" x="531.0" y="72" text-anchor="middle" font-size="13" font-weight="700" fill="#0B7F5C">{$all}</text><rect class="sw0" x="166" y="130" width="70" height="34" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text class="sw0" x="201" y="152" text-anchor="middle" font-size="13">{$w0}</text><rect class="sw1" x="242" y="130" width="70" height="34" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text class="sw1" x="277" y="152" text-anchor="middle" font-size="13">{$w1}</text><rect class="sw2" x="318" y="130" width="70" height="34" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text class="sw2" x="353" y="152" text-anchor="middle" font-size="13">{$w2}</text><rect class="sw3" x="394" y="130" width="70" height="34" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text class="sw3" x="429" y="152" text-anchor="middle" font-size="13">{$w3}</text><rect class="sw4" x="470" y="130" width="70" height="34" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text class="sw4" x="505" y="152" text-anchor="middle" font-size="13">{$w4}</text><rect class="sw5" x="546" y="130" width="70" height="34" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text class="sw5" x="581" y="152" text-anchor="middle" font-size="13">{$w5}</text><text x="150" y="196" font-size="13" fill="#1B66BC">↑ {$first}</text></svg>
SVG;
    }
}

if (!function_exists('fig_llmapi_tools')) {
    function fig_llmapi_tools(string $user, string $app, string $model, string $m1, string $m2, string $m4, string $m6, string $m7): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 340" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><defs><marker id="ts" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#1E1C52"/></marker></defs><rect x="20" y="14" width="140" height="36" rx="10" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="90" y="37" text-anchor="middle" font-weight="700">{$user}</text><line x1="90" y1="52" x2="90" y2="330" stroke="#8A87B0" stroke-width="2" stroke-dasharray="4 4"/><rect x="250" y="14" width="140" height="36" rx="10" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="320" y="37" text-anchor="middle" font-weight="700">{$app}</text><line x1="320" y1="52" x2="320" y2="330" stroke="#2F8CF0" stroke-width="2" stroke-dasharray="4 4"/><rect x="470" y="14" width="140" height="36" rx="10" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="540" y="37" text-anchor="middle" font-weight="700">{$model}</text><line x1="540" y1="52" x2="540" y2="330" stroke="#7048E8" stroke-width="2" stroke-dasharray="4 4"/><line x1="94" y1="86" x2="314" y2="86" stroke="#1E1C52" stroke-width="2" marker-end="url(#ts)"/><text x="205.0" y="80" text-anchor="middle" font-size="13">{$m1}</text><line x1="324" y1="122" x2="534" y2="122" stroke="#1E1C52" stroke-width="2" marker-end="url(#ts)"/><text x="430.0" y="116" text-anchor="middle" font-size="13">{$m2}</text><line x1="536" y1="158" x2="326" y2="158" stroke="#1E1C52" stroke-width="2" marker-end="url(#ts)"/><text x="430.0" y="152" text-anchor="middle" font-size="13">tool_use: meteo(Udine)</text><rect x="238" y="174" width="164" height="28" rx="8" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="320" y="193" text-anchor="middle" font-size="13" fill="#B84508" font-weight="700">{$m4}</text><line x1="324" y1="230" x2="534" y2="230" stroke="#1E1C52" stroke-width="2" marker-end="url(#ts)"/><text x="430.0" y="224" text-anchor="middle" font-size="13">tool_result: …</text><line x1="536" y1="266" x2="326" y2="266" stroke="#1E1C52" stroke-width="2" marker-end="url(#ts)"/><text x="430.0" y="260" text-anchor="middle" font-size="13">{$m6}</text><line x1="316" y1="302" x2="96" y2="302" stroke="#1E1C52" stroke-width="2" marker-end="url(#ts)"/><text x="205.0" y="296" text-anchor="middle" font-size="13">{$m7}</text></svg>
SVG;
    }
}

return [
    'id' => 'llm-api', 'family' => 'llm', 'after' => 'prompt-base',
    'title' => L('API dei modelli linguistici', 'Language Model APIs'), 'short' => L('API LLM', 'LLM APIs'), 'level' => L('Intermedio', 'Intermediate'),
    'desc' => L('Usare un LLM dal codice: messaggi e ruoli, token e costi, streaming, strumenti (tool use), chiavi API ed errori, output strutturato, prompt caching e batch, immagini e documenti. Esempi in Python.', 'Using an LLM from code: messages and roles, tokens and costs, streaming, tools (tool use), API keys and errors, structured output, prompt caching and batches, images and documents. Examples in Python.'),
    'lessons' => [
        lesson('messages', L('Messaggi e ruoli', 'Messages and roles'), [
            P('Le API dei modelli linguistici funzionano a **messaggi**: un elenco di turni con un ruolo (`user` per chi chiede, `assistant` per il modello) più un **system prompt** con le regole. L’API non ricorda niente tra una chiamata e l’altra: per continuare una conversazione si rimanda tutta la storia.', 'Language model APIs work with **messages**: a list of turns with a role (`user` for whoever asks, `assistant` for the model) plus a **system prompt** with the rules. The API remembers nothing between calls: to continue a conversation you send the whole history again.'),
            Fig(L(fig_llmapi_history('chiamata', 'token in ingresso', 'Ogni chiamata rimanda tutta la storia: il messaggio nuovo (★) è solo l’ultimo.'), fig_llmapi_history('call', 'input tokens', 'Each call sends the whole history again: the new message (★) is only the last one.')),
                L('Tre colonne, una per chiamata. La prima contiene system e un messaggio user; la seconda system, user, assistant e un nuovo user; la terza ancora di più. Sotto ogni colonna i token in ingresso crescono: circa 300, 900 e 1700.', 'Three columns, one per call. The first holds system and one user message; the second system, user, assistant and a new user; the third even more. Below each column the input tokens grow: about 300, 900 and 1700.'),
                L('L’API non ricorda: sei tu a rimandare la conversazione, e la paghi ogni volta.', 'The API does not remember: you send the conversation back, and pay for it every time.')),
            C('import anthropic

client = anthropic.Anthropic()   # legge la chiave da ANTHROPIC_API_KEY

risposta = client.messages.create(
    model="claude-opus-5-5",
    max_tokens=1024,
    system="Sei un tutor di programmazione paziente. Rispondi in italiano.",
    messages=[{"role": "user", "content": "Che differenza c’è tra lista e tupla in Python?"}],
)
for blocco in risposta.content:
    if blocco.type == "text":
        print(blocco.text)', 'python'),
            P('Le API di OpenAI, Google, Mistral e DeepSeek seguono lo stesso schema con nomi un po’ diversi. `max_tokens` è il tetto della risposta: se lo raggiunge, il testo si interrompe a metà.', 'The OpenAI, Google, Mistral and DeepSeek APIs follow the same pattern with slightly different names. `max_tokens` caps the answer: if it is reached, the text stops midway.'),
        ], [
            Q('m1', L('L’API ricorda la conversazione precedente?', 'Does the API remember the previous conversation?'), [L('No, si rimanda la storia a ogni chiamata', 'No, you resend the history each call'), L('Sì, sempre', 'Yes, always'), L('Solo il lunedì', 'Only on Mondays'), L('Solo con la chiave premium', 'Only with a premium key')], 0, L('Ogni richiesta è indipendente.', 'Each request is independent.')),
            Q('m2', L('Quale ruolo ha il messaggio di chi chiede?', 'Which role does the asker’s message have?'), ['user', 'assistant', 'system', 'admin'], 0, L('`assistant` è il modello.', '`assistant` is the model.')),
            Q('m3', L('Che cosa succede se la risposta raggiunge `max_tokens`?', 'What happens if the answer hits `max_tokens`?'), [L('Si interrompe a metà', 'It stops midway'), L('Continua lo stesso', 'It continues anyway'), L('Dà errore 404', 'It returns a 404'), L('Si ripete', 'It repeats')], 0, L('Meglio non tenerlo troppo basso.', 'Better not set it too low.')),
        ], task('python', L('Completa la chiamata: modello `claude-opus-5-5`, `max_tokens=500` e un messaggio `user` con il testo `"Spiegami le API REST"`.', 'Complete the call: model `claude-opus-5-5`, `max_tokens=500` and a `user` message with the text `"Spiegami le API REST"`.'), "import anthropic\nclient = anthropic.Anthropic()\nrisposta = client.messages.create(\n\n)", [re('model\s*=\s*["\']claude-opus-5-5["\']', L('Il modello', 'The model')), re('max_tokens\s*=\s*500', L('Il tetto della risposta', 'The answer cap')), re('messages\s*=\s*\[\s*\{\s*["\']role["\']\s*:\s*["\']user["\']\s*,\s*["\']content["\']\s*:\s*["\']Spiegami le API REST["\']\s*\}\s*\]', L('Il messaggio dell’utente', 'The user message'))], '', "risposta = client.messages.create(\n    model=\"claude-opus-5-5\",\n    max_tokens=500,\n    messages=[{\"role\": \"user\", \"content\": \"Spiegami le API REST\"}],\n)"), [
            dMatch(pMatch(), [['system', L('Regole generali', 'General rules')], ['user', L('Chi chiede', 'Who asks')], ['assistant', L('Il modello', 'The model')], ['max_tokens', L('Tetto della risposta', 'Answer cap')], ['messages', L('La storia della conversazione', 'The conversation history')]], L('I pezzi di una richiesta.', 'The parts of a request.')),
            dOrder(pSort(), ['messages = [{"role": "user", "content": "Ciao"}]', 'r = client.messages.create(model=M, max_tokens=500, messages=messages)', 'messages.append({"role": "assistant", "content": r.content})', 'messages.append({"role": "user", "content": "E poi?"})', 'r = client.messages.create(model=M, max_tokens=500, messages=messages)'], L('Una chat si costruisce rimandando la storia.', 'A chat is built by resending the history.')),
        ]),
        lesson('tokens', L('Token, contesto e costi', 'Tokens, context and costs'), [
            P('Le API si pagano a **token**, con prezzi diversi per i token in **ingresso** (prompt, storia, documenti) e quelli in **uscita** (la risposta, di solito più cari). Ogni risposta riporta quanti token ha usato.', 'APIs are billed per **token**, with different prices for **input** tokens (prompt, history, documents) and **output** tokens (the answer, usually pricier). Each response reports how many tokens it used.'),
            C('print(risposta.usage.input_tokens, risposta.usage.output_tokens)

# stima con prezzi di esempio: 20.000 token in ingresso a 4 $ per milione + 1.000 in uscita a 20 $ per milione
costo = 20_000 / 1_000_000 * 4 + 1_000 / 1_000_000 * 20
print(f"{costo:.3f} $")   # 0.100 $', 'python'),
            P('La **finestra di contesto** limita quanto può stare in una richiesta (storia + documenti + risposta). Per risparmiare: scegli il modello adatto al compito (i piccoli costano molto meno), accorcia la storia, e usa il **prompt caching** per le parti che si ripetono.', 'The **context window** limits how much fits in a request (history + documents + answer). To save: pick the model that suits the task (small ones cost far less), trim the history, and use **prompt caching** for repeated parts.'),
            P('Attenzione all’effetto della storia: poiché a ogni turno si rimanda tutta la conversazione, il costo in ingresso cresce turno dopo turno, e una chat lunga costa molto più della somma delle sue domande. Per questo le app tagliano o riassumono i messaggi vecchi. Quanto all’uscita, costa di più perché il modello genera un token alla volta: chiedere risposte concise (e impostare `max_tokens` con giudizio) è il risparmio più semplice.', 'Watch out for the effect of history: since the whole conversation is sent again at every turn, the input cost grows turn after turn, and a long chat costs far more than the sum of its questions. That is why apps trim or summarise old messages. As for output, it costs more because the model generates one token at a time: asking for concise answers (and setting `max_tokens` sensibly) is the simplest saving.'),
        ], [
            Q('t1', L('Che cosa si paga in un’API LLM?', 'What do you pay for in an LLM API?'), [L('Token in ingresso e in uscita', 'Input and output tokens'), L('Il numero di parole del titolo', 'The words in the title'), L('Le ore di connessione', 'Connection hours'), L('I clic', 'Clicks')], 0, L('Con prezzi diversi.', 'At different prices.')),
            Q('t2', L('Dove leggi i token usati?', 'Where do you read the tokens used?'), ['usage', 'headers', 'model', 'system'], 0, L('`input_tokens` e `output_tokens`.', '`input_tokens` and `output_tokens`.')),
            Q('t3', L('Come risparmi su un prompt lungo che si ripete?', 'How do you save on a long prompt that repeats?'), [L('Con il prompt caching', 'With prompt caching'), L('Scrivendolo in maiuscolo', 'Writing it in capitals'), L('Rimandandolo due volte', 'Sending it twice'), L('Non si può', 'You cannot')], 0, L('Le parti in cache costano molto meno.', 'Cached parts cost much less.')),
        ], task('python', L('Calcola in `costo` il prezzo di 50.000 token in ingresso a 2 $ per milione e 2.000 in uscita a 10 $ per milione, poi stampalo.', 'Compute in `costo` the price of 50,000 input tokens at $2 per million and 2,000 output tokens at $10 per million, then print it.'), '', [re('costo\s*=\s*50_?000\s*/\s*1_?000_?000\s*\*\s*2\s*\+\s*2_?000\s*/\s*1_?000_?000\s*\*\s*10', L('Il calcolo è giusto', 'The calculation is right')), re('print\s*\(', L('Lo stampi', 'You print it'))], '', "costo = 50_000 / 1_000_000 * 2 + 2_000 / 1_000_000 * 10\nprint(costo)"), [
            dMatch(pMatch(), [[L('Token in ingresso', 'Input tokens'), L('Prompt e storia', 'Prompt and history')], [L('Token in uscita', 'Output tokens'), L('La risposta', 'The answer')], [L('Contesto', 'Context'), L('Tutto quello che sta in una richiesta', 'Everything in one request')], [L('Prompt caching', 'Prompt caching'), L('Sconto sulle parti ripetute', 'Discount on repeated parts')]], L('Il conto in token.', 'The bill in tokens.')),
            dFlash(pFlash(), [[L('I token in uscita costano di solito più di quelli in ingresso', 'Output tokens usually cost more than input'), true], [L('Rimandare tutta la storia non costa nulla', 'Resending the whole history costs nothing'), false], [L('Un modello piccolo costa meno', 'A small model costs less'), true], [L('La finestra di contesto è infinita', 'The context window is infinite'), false]], L('Ogni token conta.', 'Every token counts.')),
        ]),
        lesson('streaming', L('Streaming', 'Streaming'), [
            P('Una risposta lunga può impiegare molti secondi. Con lo **streaming** il testo arriva a pezzi mentre viene generato, come nelle chat: l’utente vede subito qualcosa e le richieste lunghe non vanno in timeout.', 'A long answer can take many seconds. With **streaming** the text arrives in pieces while it is generated, as in chat apps: the user sees something at once and long requests do not time out.'),
            Fig(L(fig_llmapi_stream('senza streaming', 'con streaming', 'attesa…', 'tutto insieme', 'C’era', 'una', 'volta', 'un', 'faro', 'sul mare', 'il primo pezzo arriva subito'), fig_llmapi_stream('without streaming', 'with streaming', 'waiting…', 'all at once', 'Once', 'upon', 'a time', 'a', 'lighthouse', 'by the sea', 'the first piece arrives at once')),
                L('Due righe su una linea del tempo di 8 secondi. Senza streaming c’è una lunga attesa tratteggiata e poi la risposta compare tutta insieme. Con streaming i pezzi di testo compaiono uno dopo l’altro fin dal primo secondo.', 'Two rows on an 8-second timeline. Without streaming there is a long dashed wait and then the answer appears all at once. With streaming the pieces of text appear one after another from the first second.'),
                L('Il tempo totale è simile; cambia quando l’utente vede il primo testo.', 'The total time is similar; what changes is when the user sees the first text.')),
            C('with client.messages.stream(
    model="claude-opus-5-5",
    max_tokens=4000,
    messages=[{"role": "user", "content": "Scrivi un racconto breve sul mare."}],
) as stream:
    for pezzo in stream.text_stream:
        print(pezzo, end="", flush=True)
    finale = stream.get_final_message()   # il messaggio completo, con usage', 'python'),
            P('Sul web lo streaming arriva al browser con i **Server-Sent Events** (SSE) o i WebSocket. Il messaggio finale serve per salvare la risposta intera e i token usati.', 'On the web streaming reaches the browser through **Server-Sent Events** (SSE) or WebSockets. The final message is used to store the full answer and the tokens used.'),
            P('Il numero che conta per l’utente è il **tempo al primo token**: con lo streaming bastano pochi decimi di secondo per vedere che qualcosa si muove, anche se la risposta completa richiede comunque lo stesso tempo. Lo streaming però complica il codice: un errore può arrivare a metà risposta, e il testo va mostrato pezzo per pezzo senza rompere formattazione e caratteri. Per brevi risposte lette da un programma, una chiamata normale resta la scelta più semplice.', 'The number that matters to the user is the **time to first token**: with streaming a few tenths of a second are enough to see that something is moving, even though the full answer still takes the same time. Streaming does make the code more complex, though: an error can arrive halfway through the answer, and the text must be shown piece by piece without breaking formatting and characters. For short answers read by a program, a normal call remains the simplest choice.'),
        ], [
            Q('s1', L('Perché usare lo streaming?', 'Why use streaming?'), [L('L’utente vede il testo mentre arriva', 'The user sees text as it arrives'), L('Costa meno token', 'It costs fewer tokens'), L('Migliora la grammatica', 'It improves grammar'), L('È obbligatorio', 'It is mandatory')], 0, L('E si evitano i timeout.', 'And timeouts are avoided.')),
            Q('s2', L('Con quale tecnologia arriva spesso lo streaming al browser?', 'Which technology often carries streaming to the browser?'), ['Server-Sent Events', 'FTP', 'SMTP', 'CSV'], 0, L('O i WebSocket.', 'Or WebSockets.')),
